import{_ as i,l,o as e,c as s,v as r,p as n,x as t,d as B,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"Limit order book 结构","description":"","frontmatter":{"title":"Limit order book 结构","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/lob-structure.md","filePath":"quant/lob-structure.md","lastUpdated":1789023840000}'),c={name:"quant/lob-structure.md"};function _(h,a,b,u,m,E){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="limit-order-book-结构" tabindex="-1">Limit order book 结构 <a class="header-anchor" href="#limit-order-book-结构" aria-label="Permalink to &quot;Limit order book 结构&quot;">​</a></h1><div class="epigraph"><p>连续市场上的价格不是拍板喊出来的单一数字，而是一张按价格分层、按时间排队的未成交限价单集合；买卖双方同时挂单，撮合引擎只在交叉时成交。</p><footer>—— 据 Harris, Trading and Exchanges 对限价订单簿与连续双向拍卖的论述整理</footer></div><p><a href="/quant/futures-roll-calendar">上一课</a>把期货交割与展期日历收在制度课末。本课是「市场微观结构」的起点。后面的订单类型、数据档位、事件时间、队列、不平衡与价差分解，都默认你会这张簿的几何与优先规则，不再从「价格是什么」重讲。随机分析与财务报表已在更早的课程里；限价订单簿（limit order book, LOB）是电子盘的核心状态机。买方未成交限价单按价格从高到低排成买盘，卖方按价格从低到高排成卖盘；同一价位上再按到达次序（或按交易所规定的比例规则）排队。最佳买价与最佳卖价之间的空隙是买卖价差，中间价是对「可立即成交的公允价」的一种粗糙代理。Harris 把这类市场称为连续双向拍卖。订单类型、数据档位和价差分解分别是后面几课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若没有一张共享的簿，买卖只能靠一对一询价或做市商口头报价。那样的市场里，可成交价格是私有的，深度不可见，比较「谁更优」的成本极高。电子化之后，交易所把未成交限价单集中起来，用统一的优先规则决定下一笔成交属于谁。问题于是变成：状态要暴露到哪一层、优先权按什么词典序、价格网格多细，才能让分散的交易者在不知道对手身份的情况下仍能形成稳定的价格。</p><p>簿必须同时回答三个问题。第一，现在立刻买（或卖）要付什么价，这由最优买卖价（best bid and offer, BBO）决定。第二，再往里走一档、两档，还能成交多少，这由各价位上的剩余量决定。第三，新来的限价单应插在哪一格、排在第几位，这由价格优先加时间优先（或比例分配）决定。O&#39;Hara 强调，价格形成是交易过程的产物；LOB 正是把这个过程写成可计算状态的装置。没有它，后面的盘口不平衡、队列位置、事件时间采样都没有定义域。</p><h3 id="价位、最小变动价位与交叉" tabindex="-1">价位、最小变动价位与交叉 <a class="header-anchor" href="#价位、最小变动价位与交叉" aria-label="Permalink to &quot;价位、最小变动价位与交叉&quot;">​</a></h3><p>价格不是连续的实数，而是最小变动价位（tick）的整数倍。tick 太粗，价差常被钉在一档，簿上每一档堆着过深的队列，时间优先变得极端重要；tick 太细，价位被打散，表面上价差可以更窄，但同一「经济价位」上的量被拆到许多格子里，深度更难读。簿的几何因此不是中性的：网格宽度会改变排队博弈，也会改变看起来「有多少档」的视觉深度。</p><p>当某笔新单的买价不低于最优卖价、或卖价不高于最优买价，簿发生交叉（cross），撮合引擎按优先规则逐笔配对，直到交叉消失。未交叉的剩余量才成为新的挂单。连续市场上，正常状态是买价严格低于卖价，中间有一个非负价差；价差为零表示可以在同一价位上双向挂单但仍未交叉，价差为负则是瞬时交叉，通常只存在于撮合完成之前的消息间隔里。</p><p><span class="marginnote">中间价 \\(m=(b+a)/2\\) 不是成交价，也不是任何人必须接受的价。它只是 BBO 的对称中点。真正能立刻买到的是 \\(a\\)，立刻卖出的是 \\(b\\)。把中间价当成「真实价值」是后文 Roll、Glosten-Milgrom 要打破的习惯，而不是 LOB 自己的定义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>描述一张簿，最少需要两侧的价量序列。记 \\(t\\) 时刻买盘价位 \\(b_1\\gt b_2\\gt \\cdots\\)，对应剩余量 \\(q^b_1,q^b_2,\\ldots\\)；卖盘 \\(a_1\\lt a_2\\lt \\cdots\\)，剩余量 \\(q^a_1,q^a_2,\\ldots\\)。最优买卖价 \\(b_1,a_1\\)，价差 \\(s=a_1-b_1\\)，中间价 \\(m=(a_1+b_1)/2\\)。第 \\(k\\) 档深度就是该价位上尚未成交的限价单总量。更细的状态要把每一档拆成若干笔带编号的订单，那是 Level-3；本篇的「结构」先停在价位聚合这一层，因为优先规则首先按价格说话。</p><p>撮合的输入是事件：新限价单、市价单、撤单、改单。引擎维护两侧有序容器，在交叉时从对手方最优价开始消耗队列。价格优先意味着更优的价永远先于更差的价成交；时间优先意味着同一价位上先到的单先成交。有的合约市场在同一价位上按剩余量比例分配（pro-rata），时间优先被削弱，大单即使后到也能分到一刀。Harris 把优先规则视为市场设计的一等对象：它决定谁愿意挂单、挂在哪一档、要不要抢队。</p><h3 id="状态更新的四类原语" tabindex="-1">状态更新的四类原语 <a class="header-anchor" href="#状态更新的四类原语" aria-label="Permalink to &quot;状态更新的四类原语&quot;">​</a></h3><p>簿的演化可以收成四类原语。新增（add）：限价单不能立刻成交，插入对应价位的队尾。成交（execute）：对手方吃掉若干数量，从队头按优先规则减量，整笔耗尽则删除。撤销（cancel）：从队列中移除尚未成交的量，可能制造价位空档，使 BBO 跳到下一档。改价或改量（replace）：多数交易所把它处理成「撤旧加新」，因而丧失原有时间优先；少数允许减量且保留位置。任何更复杂的订单类型——冰山、止损转限价——最终都要落到这四类对簿的改写上。</p><p>可视化时人们常画成对称的阶梯：左侧买盘向左延伸的水平条，右侧卖盘向右延伸。阶梯的第一级最矮或最深取决于当日的挂单习惯，没有「买盘一定更深」的结构定理。真正有结构含义的是：第一档决定立刻成交的价格，前几档的累积量决定市价单的冲击路径，整张簿的形状决定大单是否值得拆开、是否值得改走暗池。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>优先规则把「谁的单先成交」从身份问题改成可验证的排序问题。价格优先保证更有攻击性的限价单先于保守的限价单；时间优先则把同一价位变成一条先进先出的队列。两者合在一起，限价单提供者面对的不是一个抽象的「深度数字」，而是自己在队列里的名次：名次靠前，被下一笔主动单扫到的概率高；名次靠后，可能还没轮到自己价格就走了。于是挂单变成一场关于价位选择与到达时刻的博弈，而不是把量随便放在某一档那么简单。</p><p>连续双向拍卖的另一面是：每个人都可以在提供流动性与索取流动性之间切换。一笔略优于对方最优价的限价单，可能在到达的瞬间就变成主动成交；一笔贴在己方最优价上的限价单，则是在出售等待期权。Harris 反复区分 maker 与 taker，不是道德分类，而是费用、价差和队列位置都沿这条界线分开。簿的结构使得这种切换是瞬时的、匿名的、由价格交叉来裁决的。</p><h3 id="深度、缺口与可见性" tabindex="-1">深度、缺口与可见性 <a class="header-anchor" href="#深度、缺口与可见性" aria-label="Permalink to &quot;深度、缺口与可见性&quot;">​</a></h3><p>深度沿价格方向的分布很少是平坦的。靠近 BBO 的档位更新最快，因为这里同时聚集了想成交的人和想排队的人；远离 BBO 的档位更像备忘录，可能是止损、冰山下单或过时的挂单。相邻价位之间若出现空档（gap），市价单会跳过空档直接打到更差的价格，瞬时冲击比「看起来有五档」要大。可见深度还不是全部深度：冰山与暗池把一部分量藏起来，簿上的阶梯是下界而不是上界。结构分析若把可见量当成可成交量，会系统性低估大单的真实对手方，也会高估自己的排队价值。</p><p><span class="marginnote">微价格（microprice）常用两侧最优档量做加权，\\(m^\\ast=(a_1 q^b_1+b_1 q^a_1)/(q^b_1+q^a_1)\\)，把中间价往量薄的一侧推。它仍是 BBO 的函数，不是模型里的有效价值。盘口稍一变，微价格就跳；把它当信号之前，先承认它只是簿几何的另一种读法。</span></p>',22)),(e(),n(p,null,{default:t(()=>[d(o,{id:"mermaid-64",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20bidSide%20%5B%E4%B9%B0%E7%9B%98%5D%0A%20%20%20%20B3%5B%22b3%20%E6%9B%B4%E4%BD%8E%E4%BB%B7%22%5D%0A%20%20%20%20B2%5B%22b2%22%5D%0A%20%20%20%20B1%5B%22b1%20%E6%9C%80%E4%BC%98%E4%B9%B0%22%5D%0A%20%20end%0A%20%20subgraph%20askSide%20%5B%E5%8D%96%E7%9B%98%5D%0A%20%20%20%20A1%5B%22a1%20%E6%9C%80%E4%BC%98%E5%8D%96%22%5D%0A%20%20%20%20A2%5B%22a2%22%5D%0A%20%20%20%20A3%5B%22a3%20%E6%9B%B4%E9%AB%98%E4%BB%B7%22%5D%0A%20%20end%0A%20%20B3%20--%3E%20B2%20--%3E%20B1%0A%20%20B1%20-.-%3E%7C%22%E4%BB%B7%E5%B7%AE%20s%22%7C%20A1%0A%20%20A1%20--%3E%20A2%20--%3E%20A3%0A%20%20MKT%5B%22%E4%B8%BB%E5%8A%A8%E4%B9%B0%22%5D%20--%3E%20A1%0A%20%20LMT%5B%22%E6%96%B0%E7%9A%84%E4%B9%B0%E9%99%90%E4%BB%B7%22%5D%20--%3E%20B1%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>LOB 是订单驱动市场的状态表示，不是所有市场的默认形态。报价驱动的做市商市场里，可见的是做市商的买卖报价，客户的意向不必以限价单形式排队；混合市场则两者并存。即使在纯电子簿上，开收盘集合竞价用的是另一套批匹配规则，连续交易时段的价格-时间优先并不自动适用。跨市场时，本地簿上的 BBO 也不等于全国最优：可成交性还受保护规则、延迟和费用影响。</p><p>结构描述还假定你看见的就是撮合引擎看见的。聚合数据把同一价位多笔单收成一个量，隐藏了队列内部的次序；快照采样会丢掉两次快照之间的增撤成交。重建簿必须用事件流，并且与交易所的优先规则一致，否则「第几档」会和真实撮合错位。tick 制度、涨跌停、拍卖时段都会让阶梯图失效或变形，不能把美股连续交易的直觉直接贴到涨跌停封板上。</p><p><span class="marginnote">不要把 LOB 图画成供需曲线。供需曲线是意愿的汇总，价格是均衡条件；订单簿是已提交、受优先规则约束的可撤销指令。簿上某一档量很大，只说明有人愿意在那个价位等待，不说明若价格走到那里需求仍在。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>限价订单簿是未成交限价单按价格分层、在同价位再按时间或比例规则排队的状态机，支撑连续双向拍卖。</li><li>最小状态是两侧有序价量；BBO 决定立刻成交价，各档深度决定冲击路径，优先规则决定新单插入何处。</li><li>更新原语只有增、成、撤、改；更复杂的订单最终都要改写这张簿。</li><li>价格优先加时间优先把流动性提供变成排队博弈；可见深度是全部深度的下界。</li><li>中间价与微价格都是 BBO 的函数，不是外生价值；交叉由撮合消除，正常连续状态保持 \\(a_1\\ge b_1\\)。</li><li>集合竞价、做市商市场、隐藏流动性与跨市场保护，都会使单张可见簿的几何不再等于可成交性。</li><li>出处：Harris, <em>Trading and Exchanges</em>；概念背景见 O&#39;Hara, <em>Market Microstructure Theory</em>。</li></ul>',6))])}const k=i(c,[["render",_]]);export{q as __pageData,k as default};
